centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
blank=(10,8)
markers=set()
ownarms={}
for r,c,v in centers:
    a={(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
    markers |= a
    ownarms[(r,c)] = a
r,c=blank
markers |= {(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
horiz=[[0]*19 for _ in range(19)]; vert=[[0]*19 for _ in range(19)]
for r,c,v in centers:
    horiz[r][c]=v; vert[r][c]=v
    for dr,dc,target in [(0,-1,horiz),(0,1,horiz),(-1,0,vert),(1,0,vert)]:
        rr,cc=r+dr,c+dc
